solution.solution.cpp:
#include <string>

class Shape
{
public:
    virtual ~Shape() = default;
    virtual int sides() const { return 0; }
    virtual std::string kind() const { return "shape"; }
};

class Polygon : public Shape
{
public:
    explicit Polygon(int sides) : m_sides{ sides } {}
    int sides() const override { return m_sides; }
    std::string kind() const final { return "polygon"; }

private:
    int m_sides{};
};

class Square final : public Polygon
{
public:
    Square() : Polygon{ 4 } {}
};

unitTests:
static_assert(std::is_final_v<Square>, "Square should be marked final");
static_assert(!std::is_final_v<Polygon>, "Polygon itself should still be inheritable");
struct TryOverride : Polygon { TryOverride() : Polygon{ 3 } {} };

TEST("polygon") { const Polygon p{ 6 }; const Shape& s{ p }; CHECK_EQ(s.sides(), 6); CHECK_EQ(s.kind(), "polygon"); }
TEST("square") { const Square q{}; const Shape& s{ q }; CHECK_EQ(s.sides(), 4); CHECK_EQ(s.kind(), "polygon"); }
TEST("classes derived from Polygon still report polygon") { const TryOverride t{}; CHECK_EQ(t.kind(), "polygon"); CHECK_EQ(t.sides(), 3); }

